//! The thin layer between a MIM app and the host's raw imports

#![no_std]

use core::fmt::{self, Write};

#[global_allocator]
static ALLOC: dlmalloc::GlobalDlmalloc = dlmalloc::GlobalDlmalloc;

// generated by tools/ffigen from sdk/mim.ffi
mod ffi;

pub mod cv;

/// The size every app draws at
pub use ffi::{SCREEN_HEIGHT, SCREEN_WIDTH};

/// The severity of a log line, as the host numbers them
#[derive(Clone, Copy)]
pub enum Level {
    Debug = 0,
    Info = 1,
    Warn = 2,
    Error = 3,
}

/// What app_tick tells the host
#[repr(i32)]
pub enum Tick {
    Quit = 0,
    Continue = 1,
}

/// An app: made by `init`, ticked once a frame, then shut down. `app!` exports it to the host
pub trait App {
    fn init() -> Self;
    fn tick(&mut self, abs_time_ms: u64, dt_seconds: f32) -> Tick;
    fn shutdown(&mut self) {}
}

/// `mim::app!(MyApp)`: exports app_init, app_tick and app_shutdown for an `App`
#[macro_export]
macro_rules! app {
    ($app:ty) => {
        const _: () = {
            // the host calls in on one thread, one export at a time
            static mut APP: Option<$app> = None;

            fn app() -> &'static mut Option<$app> {
                unsafe { &mut *(&raw mut APP) }
            }

            #[unsafe(no_mangle)]
            extern "C" fn app_init() {
                *app() = Some(<$app as $crate::App>::init());
            }

            #[unsafe(no_mangle)]
            extern "C" fn app_tick(abs_time_ms: u64, dt_seconds: f32) -> $crate::Tick {
                match app() {
                    Some(app) => $crate::App::tick(app, abs_time_ms, dt_seconds),
                    None => $crate::Tick::Quit,
                }
            }

            #[unsafe(no_mangle)]
            extern "C" fn app_shutdown() {
                if let Some(app) = app() {
                    $crate::App::shutdown(app);
                }
            }
        };
    };
}

/// Writes one line to the host's log
pub fn log(level: Level, msg: &str) {
    // the host checks the pointer and length; a valid &str always passes
    unsafe { ffi::log(level as u32, msg.as_ptr(), msg.len() as u32) }
}

/// A line being formatted on the stack; text past its capacity is dropped
pub struct Line {
    buf: [u8; ffi::LOG_MAX],
    len: usize,
}

impl Line {
    pub const fn new() -> Self {
        Line {
            buf: [0; ffi::LOG_MAX],
            len: 0,
        }
    }

    pub fn as_str(&self) -> &str {
        // write_str only ever copies whole &strs, and stops before cutting one
        unsafe { core::str::from_utf8_unchecked(&self.buf[..self.len]) }
    }
}

impl Write for Line {
    fn write_str(&mut self, s: &str) -> fmt::Result {
        if s.len() > self.buf.len() - self.len {
            return Err(fmt::Error);
        }
        self.buf[self.len..self.len + s.len()].copy_from_slice(s.as_bytes());
        self.len += s.len();
        Ok(())
    }
}

/// `log!(Level::Info, "x = {}", x)`: formats on the stack, then logs
#[macro_export]
macro_rules! log {
    ($level:expr, $($arg:tt)*) => {{
        use core::fmt::Write as _;
        let mut line = $crate::Line::new();
        let _ = write!(line, $($arg)*);
        $crate::log($level, line.as_str());
    }};
}

#[panic_handler]
fn panic(info: &core::panic::PanicInfo) -> ! {
    log!(Level::Error, "panic: {}", info.message());
    // traps: the host logs it and drops the guest
    core::arch::wasm32::unreachable()
}
